<?php namespace Workspace;
function clientDecisionForm(string $act,int $id,int $version): void { ?>
<form method="post" class="formgrid"><?php formFields($act) ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="version" value="<?= $version ?>"><label>Комментарий (обязателен при возврате)<input name="note" maxlength="1000"></label><button class="primary" name="decision" value="accept">Принять</button><button class="secondary" name="decision" value="return">Вернуть на доработку</button></form><?php }
?>
<section class="panel inset"><h1>Кабинет клиента</h1><h2><?= h($grant['project_title']) ?></h2><p>Согласованная редакция: <?= h($grant['document_title']) ?> · <?= h($grant['revision']) ?></p><p>SHA-256: <code><?= h($grant['sha256']) ?></code></p><p>Доступ до <?= h(gmdate('Y-m-d H:i',$grant['access_until'])) ?> UTC.</p><p><a href="<?= h(url('guest.download')) ?>">Скачать согласованный PDF</a></p><form method="post"><?php formFields('logout') ?><button class="secondary">Выйти</button></form><?php if ($notice): ?><p role="status" class="notice"><?= h($notice) ?></p><?php endif ?></section>
<?php if (!empty($order)): ?><section class="panel inset"><h2><?= h($order['title']) ?></h2><p><?= h($order['client_name']) ?></p><h3>Запрос</h3><p class="client-text"><?= h($order['request_text']) ?></p></section>
<?php foreach ($offers as $offer): ?><section class="panel inset"><h2>Предложение v<?= h($offer['revision']) ?> · <?= h(OFFER_STATES[$offer['status']]) ?></h2><p class="client-text"><?= h($offer['scope']) ?></p><p><b>Смета: <?= h(money($offer['total']).' '.$offer['currency']) ?></b></p>
<?php foreach ($offer['stages'] as $s): ?><article class="client-stage"><h3><?= h($s['title']) ?> · <?= h(money((int)$s['amount_minor']).' '.$offer['currency']) ?></h3><p>Срок: <?= h(displayDate($s['due_on'])) ?></p><p class="client-text"><?= h($s['scope']) ?></p><?php foreach ($s['deliveries'] as $d): ?><div class="client-stage"><h4>Результат v<?= h($d['revision']) ?> · <?= h(DELIVERY_STATES[$d['status']]) ?></h4><p class="client-text"><?= h($d['result_text']) ?></p><?php if ($d['document_id']): ?><p><a href="<?= h(url('guest.result',['id'=>$d['id']])) ?>">Скачать PDF результата</a></p><?php endif ?><?php if ($d['status']==='submitted'): clientDecisionForm('guest.delivery',(int)$d['id'],(int)$d['revision']); else: ?><p><?= h($d['decision_note']) ?> · <?= h(gmdate('Y-m-d H:i',$d['decided_at'])) ?> UTC</p><?php if ($d['status']==='accepted'): ?><p>Согласованные часы на момент приёмки: <?= h($d['accepted_minutes']) ?> мин.</p><?php endif; endif ?></div><?php endforeach ?></article><?php endforeach ?>
<?php if ($offer['status']==='offered'): clientDecisionForm('guest.offer',(int)$offer['id'],(int)$offer['version']); elseif ($offer['decided_at']): ?><p><?= h($offer['decision_note']) ?> · <?= h(gmdate('Y-m-d H:i',$offer['decided_at'])) ?> UTC</p><?php endif ?></section><?php endforeach ?><?php if (!$offers): ?><section class="panel inset"><p>Предложение пока готовится.</p></section><?php endif; endif ?>

<?php foreach($pmChanges??[] as $r): ?><section class="panel inset"><h2>Запрос на изменение #<?= h($r['number']) ?> — <?= h($r['title']) ?></h2><p><?= h(PM_STATES[$r['status']]) ?></p><h3>Предлагаемый объём</h3><p class="client-text"><?= h($r['proposed_scope']) ?></p><p>Дополнительная стоимость без налогов: <?= h(money((int)$r['amount_minor']).' '.$r['currency']) ?> · срок оплаты <?= h(displayDate($r['payment_due'])) ?></p><h3>Изменения сроков</h3><?php foreach($r['dates'] as $d): ?><p><?= h(displayDate($d['before']).' → '.displayDate($d['after'])) ?></p><?php endforeach ?><?php if(!$r['dates']): ?><p>Без сдвига сроков.</p><?php endif ?><?php if($r['status']==='pending'): clientDecisionForm('guest.pm',(int)$r['number'],1); elseif($r['decided_at']): ?><p><?= h($r['decision_note']) ?> · <?= h(gmdate('Y-m-d H:i',(int)$r['decided_at'])) ?> UTC</p><?php endif ?></section><?php endforeach ?>
